ALTER TABLE "User" ADD COLUMN "suspendedAt" TIMESTAMP(3);
CREATE TYPE "FulfillmentStatus" AS ENUM ('UNFULFILLED','PACKING','SHIPPED','DELIVERED');
ALTER TABLE "Order" ADD COLUMN "fulfillment" "FulfillmentStatus" NOT NULL DEFAULT 'UNFULFILLED', ADD COLUMN "trackingNumber" TEXT, ADD COLUMN "carrier" TEXT;
CREATE TABLE "AdminEvent" ("id" TEXT PRIMARY KEY,"actorId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"action" TEXT NOT NULL,"targetId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AdminEvent_createdAt_idx" ON "AdminEvent"("createdAt");
